const query = $input.first().json.query;

const VERIFY_TOKEN = 'my_verify_token'; // Must match what you set in Meta

if (
  query['hub.mode'] === 'subscribe' &&
  query['hub.verify_token'] === VERIFY_TOKEN
) {
  return [{ json: { challenge: query['hub.challenge'] } }];
} else {
  throw new Error('Verification failed: invalid token');
}

const body = $input.first().json.body;

const entry = body?.entry?.[0];
const change = entry?.changes?.[0];
const value = change?.value;
const message = value?.messages?.[0];

if (!message) {
  return [{ json: { skip: true } }];
}

const senderName = value?.contacts?.[0]?.profile?.name || 'User';

if (message.type === 'image') {
  return [{
    json: {
      skip: false,
      messageType: 'image',
      from: message.from,
      mediaId: message.image.id,
      caption: message.image.caption || '',
      messageId: message.id,
      timestamp: message.timestamp,
      senderName
    }
  }];
}

if (message.type !== 'text') {
  return [{ json: { skip: true } }];
}

return [{
  json: {
    skip: false,
    messageType: 'text',
    from: message.from,
    userMessage: message.text.body,
    messageId: message.id,
    timestamp: message.timestamp,
    senderName
  }
}];

const event = $input.first().json.body;
if (!event || event.event !== 'charge.success') return [];

const data = event.data;
const meta = (typeof data.metadata === 'object' && data.metadata) ? data.metadata : {};

const enrollId   = meta.enrollment_id || null;
const waSenderId = meta.wa_sender_id  || null;
const phone      = meta.phone || data.customer?.phone || null;
const fullName   = meta.full_name || data.customer?.first_name || 'Enrollee';
const planType   = meta.plan_type || 'Individual';
const amountPaid = (data.amount / 100).toLocaleString('en-NG');
const reference  = data.reference;
const channel    = data.channel || 'card';

// If no enrollment_id, we can't update the sheet — log and stop
if (!enrollId) {
  console.log('No enrollment_id in metadata — cannot match record. Reference: ' + reference);
  return [];
}

return [{
  json: {
    enrollment_id: enrollId,
    phone,
    full_name:    fullName,
    plan_type:    planType,
    amount_paid:  amountPaid,
    reference,
    channel,
    wa_sender_id: waSenderId,
    payment_note: `Paystack verified — Ref: ${reference} | Channel: ${channel} | Amount: ₦${amountPaid}`
  }
}];

const enrollment = $input.first().json;
const paystack   = $('Parse KADCHMA Paystack Event').first().json;

const phone     = enrollment.phone_number || paystack.phone;
const name      = enrollment.first_name   || paystack.full_name || 'Enrollee';
const enrollId  = enrollment.enrollment_id || paystack.enrollment_id;
const amount    = paystack.amount_paid;
const plan      = enrollment.plan_type    || paystack.plan_type;
const facility  = enrollment.facility_of_choice || 'your chosen facility';
const waSenderId = paystack.wa_sender_id || null;

const msg = `✅ *Payment Confirmed — KADCHMA Enrollment*

Dear ${name},

Your payment of ₦${amount} has been successfully received and your enrollment is now active.

*Enrollment ID:* ${enrollId}
*Plan:* ${plan}
*Facility of Choice:* ${facility}

Your insurance card and policy documents will be issued within 5–7 working days.

For support, reply *HELP* anytime or call the KADCHMA helpline.

Thank you for enrolling! 🏥`;

return [{
  json: {
    phone,
    wa_sender_id:  waSenderId,
    reply_text:    msg,
    enrollment_id: enrollId,
    amount_paid:   amount,
    can_send_wa:   !!(waSenderId),
    first_name:    name,
    facility,
    plan
  }
}];

